### Implement two-way IPC with ipcMain.handle and ipcRenderer.invoke

Source: https://github.com/electron/electron/blob/main/docs/tutorial/ipc.md

Pair ipcRenderer.invoke in the preload script with ipcMain.handle in the main process to asynchronously return results to the renderer. Errors thrown through handle in the main process serialize only their message property to the renderer. Do not expose ipcRenderer.invoke directly across the context bridge to maintain security.

```javascript
const { app, BrowserWindow, dialog, ipcMain } = require('electron')

const path = require('node:path')

// ...

async function handleFileOpen() {
  const { canceled, filePaths } = await dialog.showOpenDialog({})
  if (!canceled) {
    return filePaths[0]
  }
}

function createWindow() {
  const mainWindow = new BrowserWindow({
    webPreferences: {
      preload: path.join(__dirname, 'preload.js')
    }
  })
  mainWindow.loadFile('index.html')
}

app.whenReady().then(() => {
  ipcMain.handle('dialog:openFile', handleFileOpen)
  createWindow()
})
// ...
```

```javascript
const { contextBridge, ipcRenderer } = require('electron')

contextBridge.exposeInMainWorld('electronAPI', {
  openFile: () => ipcRenderer.invoke('dialog:openFile')
})
```

